<script setup>
import { computed } from 'vue';
import { daysBetween,d10,fdate,ftime,money,num,PLAN_STATE } from '../../lib/client-info';
import ClientSections from './ClientSections.vue';
import ClientPhone from './ClientPhone.vue';
const props=defineProps({bundle:Object,metrics:Object});
const worst=computed(()=>props.metrics.alerts.some(row=>row.c==='neg')?'neg':props.metrics.alerts.some(row=>row.c==='warn')?'warn':'ok');
const sections=computed(()=>[
 {id:'alerts',icon:worst.value==='ok'?'🌿':'🚨',title:'Attention needed',badge:props.metrics.alerts.filter(row=>row.c!=='ok').length||'✓',tone:worst.value,wide:true},
 {id:'money',icon:'💰',title:'Money snapshot',badge:props.metrics.due.pending>0?money(props.metrics.due.pending):'No dues'},
 {id:'progress',icon:'📈',title:'Treatment progress',badge:props.metrics.completion+'%'},
 {id:'upcoming',icon:'🗓️',title:'Coming up',badge:[props.metrics.nextAppt,props.metrics.nextFu,props.metrics.due.next].filter(Boolean).length},
 {id:'profile',icon:'🪪',title:'Client profile'}, {id:'contacts',icon:'📱',title:'Contact numbers',badge:props.metrics.phones.length},
 {id:'branches',icon:'🏢',title:'Branch presence',badge:props.metrics.branchList.length}, {id:'attended',icon:'👩‍⚕️',title:'Most attended by',badge:props.metrics.practitioners.length},
 {id:'timeline',icon:'🕒',title:'Recent activity',badge:timeline.value.length,wide:true},
]);
const timeline=computed(()=>[
 ...props.bundle.sessions.slice(0,12).map(row=>({date:d10(row.start_date||row.creation),icon:'💆',title:'Session — '+(row.therapy_type||'Therapy'),detail:row.custom_practitioner_name||row.practitioner||''})),
 ...props.bundle.invoices.slice(0,8).map(row=>({date:d10(row.posting_date),icon:'🧾',title:'Invoice '+row.name+' — '+money(row.base_grand_total),detail:num(row.outstanding_amount)>0?'Balance '+money(row.outstanding_amount):'Paid'})),
 ...props.bundle.appts.slice(0,8).map(row=>({date:d10(row.appointment_date),icon:'📅',title:'Appointment — '+(row.appointment_type||'Visit'),detail:row.status||''})),
 ...props.bundle.followups.slice(0,8).map(row=>({date:d10(row.followup_date||row.creation),icon:'📞',title:'Followup — '+(row.followup_type||''),detail:row.status||''})),
].filter(row=>row.date).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14));
const profileFields=computed(()=>{const p=props.bundle.patient,m=props.metrics;return[['Client ID',m.cid.real?m.cid.id:'⚠ Not set ('+m.cid.id+')'],['Client name',p.patient_name||props.bundle.pid],['Gender',m.gender.e+' '+m.gender.t],['Date of birth',p.dob?fdate(p.dob)+' ('+Math.floor(daysBetween(p.dob,m.t)/365.25)+' yrs)':'—'],['Registered on',fdate(m.registered)],['First plan',fdate(m.joined)],['Joined by',m.joinedBy],['Home branch',m.home],['Medical status',m.med.isMedical?'🩺 Medical':'🌿 Non-medical'],['Blood group',p.blood_group||'—'],['Email',p.email?String(p.email).replace(/^(.{2}).*(@.*)$/,'$1•••$2'):'—'],['Occupation',p.occupation||p.custom_occupation||'—']];});
</script>
<template><ClientSections name="overview" :sections="sections"><template #alerts><div class="c3-alerts"><div v-for="(row,index) in metrics.alerts" :key="index" class="c3-alert" :class="'tone-'+row.c"><span>{{ row.e }}</span><p>{{ row.t }}</p></div></div></template><template #money><div class="c3-money-hero" :class="metrics.due.overdue?'tone-neg':metrics.due.pending?'tone-warn':'tone-ok'"><small>Due amount</small><b>{{ money(metrics.due.pending) }}</b><span>{{ metrics.due.overdue?'⏰ '+money(metrics.due.overdueAmt)+' crossed due date (oldest '+fdate(metrics.due.oldestOverdue)+')':metrics.due.next?'📆 Next due '+fdate(metrics.due.next)+' — '+money(metrics.due.nextAmt):'✓ No pending balance' }}</span></div><div class="c3-grid c3-g3"><div v-for="[label,value] in [['Total billed',money(metrics.billed)],['Lifetime paid',money(metrics.paid)],['Invoices with balance',metrics.due.withDues+' of '+metrics.invCount],['Client tier',metrics.tier?.key||'Regular'],['Next tier',metrics.nextTier?metrics.nextTier.key+' in '+money(metrics.nextTier.min-metrics.paid):'👑 Highest tier'],['Overdue invoices',metrics.due.overdue]]" :key="label" class="c3-kv"><small>{{ label }}</small><b>{{ value }}</b></div></div></template><template #progress><div class="c3-grid c3-g4"><div v-for="[label,value] in [['Completion',metrics.completion+'%'],['Sessions',metrics.doneS+' / '+metrics.totalS],['Avg visits / month',metrics.avgMonthly.toFixed(1)],['Plan pace needed',metrics.expectedMonthly?metrics.expectedMonthly.toFixed(1)+' / month':'—']]" :key="label" class="c3-kv"><small>{{ label }}</small><b>{{ value }}</b></div></div><div class="c3-plan-mini"><div v-for="row in metrics.planView.filter(row=>row.h.state!=='cancelled').slice(0,8)" :key="row.plan.name" class="c3-pm" :class="'tone-'+PLAN_STATE[row.h.state].c"><div class="c3-pm-top"><b>{{ row.rows.length?row.rows.map(therapy=>therapy.therapy).join(', '):row.plan.name }}</b><span class="c3-pill" :class="'tone-'+PLAN_STATE[row.h.state].c">{{ PLAN_STATE[row.h.state].l }}</span></div><div class="c3-pm-meta"><span>{{ row.plan.name }}</span><span>🏢 {{ row.plan.branch||'—' }}</span><span>{{ row.h.done }}/{{ row.h.total }}</span><span>Ends {{ fdate(row.h.due) }}{{ row.h.estimated?' (est.)':'' }}</span></div><span class="c3-meter"><i :style="{width:row.h.pct+'%'}"></i></span></div></div></template><template #upcoming><div class="c3-grid c3-g3"><div v-for="[icon,label,value,detail] in [['📅','Next appointment',metrics.nextAppt?fdate(metrics.nextAppt.appointment_date)+' '+ftime(metrics.nextAppt.appointment_time):'Not booked',metrics.nextAppt?.branch||''],['📞','Next followup',metrics.nextFu?fdate(metrics.nextFu.next_followup_date):metrics.overdueFu.length?metrics.overdueFu.length+' overdue':'None scheduled',metrics.nextFu?.followup_type||''],['💰','Next due date',metrics.due.overdue?'Overdue now':fdate(metrics.due.next),metrics.due.overdue?money(metrics.due.overdueAmt):metrics.due.next?money(metrics.due.nextAmt):'No pending dues']]" :key="label" class="c3-up tone-info"><span>{{ icon }}</span><div><small>{{ label }}</small><b>{{ value }}</b><em>{{ detail }}</em></div></div></div></template><template #profile><div class="c3-grid c3-g3"><div v-for="[label,value] in profileFields" :key="label" class="c3-kv"><small>{{ label }}</small><b>{{ value }}</b></div></div></template><template #contacts><div class="c3-phones"><ClientPhone v-for="row in metrics.phones" :key="row.number" :value="row.number" :label="row.label" /></div><p class="c3-note">🔒 Numbers stay masked. Hover or tab onto a number to reveal it.</p></template><template #branches><ol class="c3-journey"><li v-for="row in metrics.branchList" :key="row.branch" :class="{'is-home':row.branch===metrics.home}"><div><b>{{ row.branch }}</b><span v-if="row.branch===metrics.home" class="c3-pill tone-ok">Home</span><span>{{ [row.plans&&row.plans+' plans',row.active&&row.active+' active',row.sessions&&row.sessions+' sessions',row.invoices&&row.invoices+' invoices'].filter(Boolean).join(', ') }}</span></div><em>{{ fdate(row.first) }} – {{ fdate(row.last) }}</em></li></ol></template><template #attended><div class="c3-bars"><div v-for="([name,count],index) in metrics.practitioners.slice(0,6)" :key="name" class="c3-bar"><span class="c3-bar-l">{{ index===0?'🏅 ':'' }}{{ name }}</span><span class="c3-bar-t"><i :style="{width:count/(metrics.practitioners[0]?.[1]||1)*100+'%'}"></i></span><b>{{ count }} ({{ Math.round(count/bundle.sessions.length*100) }}%)</b></div></div></template><template #timeline><ol class="c3-timeline"><li v-for="(row,index) in timeline" :key="index"><span class="c3-tl-d">{{ fdate(row.date) }}</span><span class="c3-tl-e">{{ row.icon }}</span><div><b>{{ row.title }}</b><em>{{ row.detail }}</em></div></li></ol></template></ClientSections></template>
